1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
4	import { join } from "node:path";
5	
6	/* ------------------------------------------------------------------ *
7	 * Live-chat AGENT tool routing + graceful degradation.
8	 *
9	 * The reworked assistant runs an agentic tool loop for EVERY visitor
10	 * (lib/kb-tools.ts): PUBLIC tools for anyone, account tools only for a
11	 * signed-in customer. When the model can't run at all, the front door
12	 * (lib/kb.ts → degradedReply) must degrade to ONE warm, honest message
13	 * that offers a human follow-up — never a dumped blog link.
14	 *
15	 * These are behavioural checks, run against the real modules. The lib
16	 * files open with `import "server-only"`, a build-time no-op that isn't
17	 * installed for a bare `tsx` run, so we first drop the same empty shim
18	 * Next.js provides on the server. It stays hermetic: get_plans and the
19	 * sign-in guard are pure (no DB), and degradedReply is a pure string.
20	 * ------------------------------------------------------------------ */
21	
22	// `import "server-only"` resolves to an empty module on the server. Provide it
23	// (idempotently) BEFORE the dynamic imports below so the modules load under tsx.
24	//
25	// This checks CONTENT, not just presence, on purpose (2026-08-26): the real
26	// npm package `server-only` (facebook/react's own marker package, published to
27	// the registry) can ALSO end up in node_modules as an unrelated dependency's
28	// transitive dependency — e.g. `@paypal/react-paypal-js` depends on it for an
29	// entry point (`v6/server.js`) this codebase never imports. Its DEFAULT export
30	// condition unconditionally throws "This module cannot be imported from a
31	// Client Component…" (it only resolves to a no-op under the `react-server`
32	// export condition, which a bare `tsx` run never sets). A presence-only check
33	// would find that real package's `index.js` already sitting at this path and
34	// skip writing our shim over it — passing under `npm ci` today, then breaking
35	// the instant an unrelated dependency bump makes `server-only` a real installed
36	// package, exactly as it did here. Checking content makes ours win regardless.
37	const shimDir = join(import.meta.dirname, "..", "node_modules", "server-only");
38	const shimIndexPath = join(shimDir, "index.js");
39	const OUR_SHIM = "module.exports = {};\n";
40	if (!existsSync(shimIndexPath) || readFileSync(shimIndexPath, "utf8") !== OUR_SHIM) {
41	  mkdirSync(shimDir, { recursive: true });
42	  writeFileSync(
43	    join(shimDir, "package.json"),
44	    '{"name":"server-only","version":"0.0.0","main":"index.js","browser":"index.js"}\n',
45	  );
46	  writeFileSync(shimIndexPath, OUR_SHIM);
47	}
48	
49	// Lazy loaders — the modules import cleanly now that the shim is in place. ESM
50	// caches, so importing per-test is cheap. (Top-level await isn't available under
51	// the repo's CJS test transform, so we can't hoist these.)
52	const kbTools = () => import("../lib/kb-tools.ts");
53	const kb = () => import("../lib/kb.ts");
54	
55	test("an account tool without a signed-in user is a gentle sign-in ask, never a throw", async () => {
56	  const { runChatTool } = await kbTools();
57	  // list_services is an ACCOUNT tool — with no userId it must NOT hit the DB and
58	  // must NOT throw; it returns a string steering the visitor to sign in.
59	  const r = await runChatTool(null, "list_services", {});
60	  assert.equal(typeof r, "string");
61	  assert.ok(r.length > 0);
62	  assert.match(r, /sign in/i);
63	  assert.match(r, /\/login/); // points them at the real login route
64	});
65	
66	test("public tools route WITHOUT a user (no sign-in guard)", async () => {
67	  const { runChatTool, runPublicTool } = await kbTools();
68	  // get_plans is pure (reads the static PLAN_CARDS catalog) — a clean check that
69	  // an anonymous visitor is served the public path, not the account guard.
70	  const plans = await runPublicTool("get_plans", { product: "vps" });
71	  assert.equal(typeof plans, "string");
72	  assert.match(plans, /PLAN CATALOG/);
73	  assert.doesNotMatch(plans, /sign in/i);
74	
75	  // runChatTool must also dispatch a PUBLIC tool name for a null user rather than
76	  // fall into the account sign-in guard.
77	  const status = await runChatTool(null, "check_platform_status", {});
78	  assert.equal(typeof status, "string");
79	  assert.doesNotMatch(status, /sign in/i);
80	});
81	
82	test("an unknown tool name is a safe error string, never a throw", async () => {
83	  const { runPublicTool } = await kbTools();
84	  const r = await runPublicTool("does_not_exist", {});
85	  assert.equal(typeof r, "string");
86	  assert.match(r, /unknown tool/i);
87	});
88	
89	test("degradedReply offers a human/contact path and never dumps a blog link", async () => {
90	  const { degradedReply } = await kb();
91	  for (const reason of ["no_key", "error", "over_cap"] as const) {
92	    const r = degradedReply(reason, "Sam");
93	    assert.ok(r.trim().length > 20, `${reason} must be a real message`);
94	    // The whole point of the rework: no blog-snippet/article link as "the answer".
95	    assert.doesNotMatch(r, /\/blog\//i, `${reason} must not link a blog post`);
96	    // It must still be useful — point at contact/pricing/help/status, not a dead end.
97	    assert.match(r, /contact|pricing|status|help|email/i, `${reason} must offer a next step`);
98	  }
99	  // A name, when present, is used.
100	  assert.match(degradedReply("error", "Sam"), /Sam/);
101	});
