1	import "server-only";
2	import { db } from "@/lib/db";
3	import type { TicketStatus } from "@prisma/client";
4	import type { ClaudeToolDef } from "@/lib/anthropic";
5	import { formatMoney, currentCurrency } from "@/lib/tax";
6	import { cardDisplayLabel, hasChargeableCard } from "@/lib/stripe-cards";
7	import { PLAN_CARDS } from "@/lib/kb-plans";
8	import { mirrorNewTicketToDiscord } from "@/lib/discord-bridge";
9	
10	// ---------------------------------------------------------------------------
11	// Per-customer, READ-ONLY diagnostic tools for the AI chat assistant.
12	//
13	// Every query in this file is scoped to the trusted `userId` FUNCTION ARGUMENT
14	// (the signed-in customer). The tool `input` is NEVER trusted to carry a userId
15	// or any ownership claim — it may only carry a service `id`, which is then
16	// re-checked to belong to `userId` before anything is returned. Nothing here
17	// writes, updates, or deletes; nothing here returns another user's row.
18	//
19	// Grounding (all confirmed against prisma/schema.prisma):
20	//   - Server            userId  — VPS, game servers (gamePlanId), NxCloud VMs
21	//   - HostingAccount    userId  — shared hosting
22	//   - Domain            userId
23	//   - EmailSubscription userId  — business email (Mailbox via subscription)
24	//   - Volume            userId  — block-storage add-on disks
25	//   - NxCloudInstance   userId  — managed Nextcloud
26	//   - Invoice           userId  — money in integer CENTS
27	//   - WalletTransaction userId  — wallet credits/debits in CENTS
28	//   - Ticket            userId  — support tickets
29	//   - User              balanceCents, signupCreditCents, card* mirror fields
30	//
31	// Money is stored as integer CENTS everywhere and displayed with formatMoney()
32	// in the account's configured display currency (default USD). Secrets
33	// (rootPassword*, *PasswordEnc, *PassEnc, tokens) are never read or returned;
34	// only the stored card brand/last4 are surfaced.
35	// ---------------------------------------------------------------------------
36	
37	/** Statuses treated as "still open" for a support ticket (i.e. not CLOSED). */
38	const OPEN_TICKET_STATUSES: TicketStatus[] = ["OPEN", "ANSWERED", "CUSTOMER_REPLY"];
39	
40	/** Map the User's stored card mirror fields onto the shared CardDisplay shape. */
41	function cardOf(user: {
42	  cardBrand: string | null;
43	  cardLast4: string | null;
44	  cardExpMonth: number | null;
45	  cardExpYear: number | null;
46	}) {
47	  return {
48	    brand: user.cardBrand,
49	    last4: user.cardLast4,
50	    expMonth: user.cardExpMonth,
51	    expYear: user.cardExpYear,
52	  };
53	}
54	
55	/** "2026-08-15" or "—" for a nullable date. */
56	function ymd(d: Date | null | undefined): string {
57	  return d ? d.toISOString().slice(0, 10) : "—";
58	}
59	
60	/** Short, model-friendly one-liner joiner. */
61	function lines(...parts: (string | false | null | undefined)[]): string {
62	  return parts.filter(Boolean).join("\n");
63	}
64	
65	/** Classify a Server row into a customer-facing service type. */
66	function serverType(s: { gamePlanId: string | null; nxcloudInstance: unknown | null }): string {
67	  if (s.nxcloudInstance) return "nxcloud";
68	  if (s.gamePlanId) return "game";
69	  return "vps";
70	}
71	
