172	
173	// ---------------------------------------------------------------------------
174	// PUBLIC tools — available to EVERY visitor (signed in or not). These never
175	// touch a specific customer's private data, so they need no userId scoping.
176	// ---------------------------------------------------------------------------
177	export const PUBLIC_TOOLS: ClaudeToolDef[] = [
178	  {
179	    name: "check_platform_status",
180	    description:
181	      "Check Nxeon's LIVE platform status for any ongoing incident, outage, or " +
182	      "maintenance, plus any active operational announcement. Call this whenever a " +
183	      "visitor reports something is down/slow/not working, or asks 'is there an outage', " +
184	      "BEFORE reassuring them — so you never say 'all good' during a real incident. No input.",
185	    input_schema: { type: "object", properties: {}, required: [] },
186	  },
187	  {
188	    name: "get_plans",
189	    description:
190	      "The real Nxeon plan catalog with exact prices and specs (shared hosting, VPS, " +
191	      "game servers, business email). Use this to ground any pricing/specs answer instead " +
192	      "of relying on memory, and to pick the right plan-card keys. Optional { product } to " +
193	      "filter: 'hosting' | 'vps' | 'game' | 'email'.",
194	    input_schema: {
195	      type: "object",
196	      properties: {
197	        product: {
198	          type: "string",
199	          description: "Optional filter: hosting | vps | game | email.",
200	          enum: ["hosting", "vps", "game", "email"],
201	        },
202	      },
203	      required: [],
204	    },
205	  },
206	  {
207	    name: "search_help",
208	    description:
209	      "Search Nxeon's help articles and blog guides for how-to detail on a specific topic " +
210	      "(e.g. 'point a domain', 'install WordPress', 'connect Cloudflare', 'SFTP'). Returns " +
211	      "the most relevant snippets to ground a step-by-step answer. Use for long-tail " +
212	      "how-to questions the core knowledge base doesn't fully cover. Input { query }.",
213	    input_schema: {
214	      type: "object",
215	      properties: {
216	        query: { type: "string", description: "What to search for." },
217	      },
218	      required: ["query"],
219	    },
220	  },
221	];
222	
223	// ---------------------------------------------------------------------------
224	// Executor
225	// ---------------------------------------------------------------------------
226	
227	/**
228	 * Execute a tool STRICTLY scoped to `userId`. Read-only. Returns a concise,
229	 * model-friendly string. Never returns another user's data. On an unknown tool
230	 * or any error, returns a short error string (never throws).
231	 */
232	export async function runAccountTool(
233	  userId: string,
234	  name: string,
235	  input: unknown,
236	): Promise<string> {
237	  try {
238	    if (!userId) return "Error: no signed-in customer.";
239	    const currency = await currentCurrency();
240	    const money = (cents: number) => formatMoney(cents, currency);
241	
242	    switch (name) {
243	      case "get_account_overview":
244	        return await accountOverview(userId, money);
245	      case "list_services":
246	        return await listServices(userId);
247	      case "get_service":
248	        return await getService(userId, input);
249	      case "list_invoices":
250	        return await listInvoices(userId, input, money);
251	      case "get_billing_status":
252	        return await billingStatus(userId, money);
253	      case "list_tickets":
254	        return await listTickets(userId);
255	      case "open_support_ticket":
256	        return await openTicket(userId, input);
257	      default:
258	        return `Error: unknown tool "${name}".`;
259	    }
260	  } catch (err) {
261	    const msg = err instanceof Error ? err.message : String(err);
262	    return `Error running ${name}: ${msg}`;
263	  }
264	}
265	
266	/** The tools a given visitor may use: everyone gets PUBLIC_TOOLS; a signed-in
267	 *  customer additionally gets the account (read + open-ticket) tools. */
268	export function chatToolsFor(userId: string | null | undefined): ClaudeToolDef[] {
269	  return userId ? [...PUBLIC_TOOLS, ...ACCOUNT_TOOLS] : [...PUBLIC_TOOLS];
270	}
271	
272	const PUBLIC_TOOL_NAMES = new Set(PUBLIC_TOOLS.map((t) => t.name));
273	
274	/**
275	 * Unified executor for the chat agent. Routes public tools to the unscoped
276	 * runner and account tools to the userId-scoped runner. An account tool
277	 * requested without a signed-in user returns a gentle "please sign in" string
278	 * (never throws, never leaks). Read-only except open_support_ticket, which only
279	 * ever creates a ticket owned BY the calling customer.
280	 */
281	export async function runChatTool(
282	  userId: string | null | undefined,
283	  name: string,
284	  input: unknown,
285	): Promise<string> {
286	  if (PUBLIC_TOOL_NAMES.has(name)) return runPublicTool(name, input);
287	  if (!userId) {
288	    return "This looks up a specific customer's account, which needs them signed in. Ask the visitor to sign in at /login (or create an account at /register) and reopen chat there, and their account details will be available.";
289	  }
290	  return runAccountTool(userId, name, input);
291	}
292	
293	/** Execute a PUBLIC tool (no customer scoping needed). Never throws. */
294	export async function runPublicTool(name: string, input: unknown): Promise<string> {
295	  try {
296	    switch (name) {
297	      case "check_platform_status":
298	        return await platformStatus();
299	      case "get_plans":
300	        return planCatalog(input);
301	      case "search_help":
302	        return await searchHelp(input);
303	      default:
304	        return `Error: unknown tool "${name}".`;
305	    }
306	  } catch (err) {
307	    const msg = err instanceof Error ? err.message : String(err);
308	    return `Error running ${name}: ${msg}`;
309	  }
310	}
311	
312	// ---------------------------------------------------------------------------
313	// Tool implementations (each scoped to userId)
314	// ---------------------------------------------------------------------------
315	
316	async function accountOverview(userId: string, money: (c: number) => string): Promise<string> {
317	  const now = new Date();
318	  const [user, servers, hosting, emailSubs, domains, volumes, openInvoices, openTickets] =
319	    await Promise.all([
320	      db.user.findUnique({
321	        where: { id: userId },
322	        select: {
323	          balanceCents: true,
324	          signupCreditCents: true,
325	          cardBrand: true,
326	          cardLast4: true,
327	          cardExpMonth: true,
328	          cardExpYear: true,
329	          stripeCustomerId: true,
330	          stripePaymentMethodId: true,
331	        },
332	      }),
333	      db.server.findMany({
334	        where: { userId, status: { not: "DELETING" } },
335	        select: { status: true, gamePlanId: true, nxcloudInstance: { select: { id: true } } },
336	      }),
337	      db.hostingAccount.groupBy({
338	        by: ["status"],
339	        where: { userId, status: { not: "DELETING" } },
340	        _count: true,
341	      }),
342	      db.emailSubscription.count({ where: { userId } }),
343	      db.domain.count({ where: { userId } }),
344	      db.volume.count({ where: { userId, status: { not: "DELETING" } } }),
345	      db.invoice.findMany({
346	        where: { userId, status: "OPEN" },
347	        select: { amountCents: true },
348	      }),
349	      db.ticket.count({ where: { userId, status: { in: OPEN_TICKET_STATUSES } } }),
350	    ]);
351	
352	  if (!user) return "Error: customer not found.";
353	
354	  // Server breakdown by type + status.
355	  const vps = servers.filter((s) => !s.gamePlanId && !s.nxcloudInstance);
356	  const game = servers.filter((s) => s.gamePlanId && !s.nxcloudInstance);
357	  const nxcloud = servers.filter((s) => s.nxcloudInstance);
358	  const statusMix = (rows: { status: string }[]) => {
359	    const m: Record<string, number> = {};
360	    for (const r of rows) m[r.status] = (m[r.status] ?? 0) + 1;
361	    return Object.entries(m)
362	      .map(([k, v]) => `${v} ${k}`)
363	      .join(", ");
364	  };
365	
366	  const svcLine = (label: string, rows: { status: string }[]) =>
367	    rows.length ? `${label}: ${rows.length} (${statusMix(rows)})` : null;
368	
369	  const hostingTotal = hosting.reduce((n, h) => n + h._count, 0);
370	  const hostingMix = hosting.map((h) => `${h._count} ${h.status}`).join(", ");
371	
372	  const cardLabel = cardDisplayLabel(cardOf(user));
373	  const overdueServers = await db.server.count({
374	    where: { userId, isFree: false, expiresAt: { lt: now }, status: { in: ["RUNNING", "STOPPED", "SUSPENDED"] } },
375	  });
376	
377	  const unpaidTotal = openInvoices.reduce((n, i) => n + i.amountCents, 0);
378	  const creditCents = user.balanceCents + user.signupCreditCents;
379	
380	  return lines(
381	    "ACCOUNT OVERVIEW",
382	    "Services:",
383	    svcLine("  VPS", vps),
384	    svcLine("  Game servers", game),
385	    svcLine("  Managed Nextcloud", nxcloud),
386	    hostingTotal ? `  Shared hosting: ${hostingTotal} (${hostingMix})` : null,
387	    emailSubs ? `  Business email: ${emailSubs} subscription(s)` : null,
388	    domains ? `  Domains: ${domains}` : null,
389	    volumes ? `  Storage volumes: ${volumes}` : null,
390	    !vps.length && !game.length && !nxcloud.length && !hostingTotal && !emailSubs && !domains && !volumes
391	      ? "  (no active services)"
392	      : null,
393	    "Billing:",
394	    `  Payment card on file: ${cardLabel ? cardLabel : "none"}${cardLabel && !hasChargeableCard(user) ? " (not currently chargeable)" : ""}`,
395	    `  Unpaid invoices: ${openInvoices.length}${openInvoices.length ? ` totaling ${money(unpaidTotal)}` : ""}`,
396	    overdueServers ? `  Past-due services in dunning: ${overdueServers}` : "  Past-due services: 0",
397	    `  Wallet balance / credit: ${money(creditCents)}`,
398	    `Open support tickets: ${openTickets}`,
399	  );
400	}
401	
402	async function listServices(userId: string): Promise<string> {
403	  const [servers, hosting, emailSubs, domains, volumes] = await Promise.all([
404	    db.server.findMany({
405	      where: { userId, status: { not: "DELETING" } },
406	      select: {
407	        id: true,
408	        name: true,
409	        label: true,
410	        status: true,
411	        expiresAt: true,
412	        gamePlanId: true,
413	        plan: { select: { name: true } },
414	        gamePlan: { select: { name: true, gameFamily: true } },
415	        nxcloudInstance: { select: { id: true, subdomain: true } },
416	      },
417	      orderBy: { createdAt: "asc" },
418	      take: 20,
419	    }),
420	    db.hostingAccount.findMany({
421	      where: { userId, status: { not: "DELETING" } },
422	      select: {
423	        id: true,
424	        primaryDomain: true,
425	        status: true,
426	        expiresAt: true,
427	        plan: { select: { name: true } },
428	      },
429	      orderBy: { createdAt: "asc" },
430	      take: 20,
431	    }),
432	    db.emailSubscription.findMany({
433	      where: { userId },
