849	async function openTicket(userId: string, input: unknown): Promise<string> {
850	  const obj = (typeof input === "object" && input ? input : {}) as Record<string, unknown>;
851	  const subject = typeof obj.subject === "string" ? obj.subject.trim().slice(0, 200) : "";
852	  const body = typeof obj.body === "string" ? obj.body.trim().slice(0, 5000) : "";
853	  const priority = typeof obj.priority === "string" && TICKET_PRIORITIES.has(obj.priority.toUpperCase())
854	    ? (obj.priority.toUpperCase() as "LOW" | "NORMAL" | "HIGH" | "URGENT")
855	    : "NORMAL";
856	  if (!subject || !body) return "Error: open_support_ticket needs both a subject and a body.";
857	
858	  // Guard against duplicate/spam tickets from one chat: cap open tickets.
859	  const openCount = await db.ticket.count({
860	    where: { userId, status: { in: OPEN_TICKET_STATUSES } },
861	  });
862	  if (openCount >= 8) {
863	    return "This customer already has several open tickets — do not open another; point them to /dashboard/support to follow up on an existing one.";
864	  }
865	
866	  const ticket = await db.ticket.create({
867	    data: {
868	      userId,
869	      subject,
870	      priority,
871	      messages: { create: { authorId: userId, body, isStaff: false } },
872	    },
873	    select: { id: true },
874	  });
875	  // Discord bridge (Phase 1 mirror): best-effort, never blocks the AI agent's
876	  // response to the customer — see lib/discord-bridge.ts's top-of-file comment.
877	  await mirrorNewTicketToDiscord(ticket.id);
878	  return lines(
879	    `Opened support ticket [${ticket.id}] "${subject}" (priority ${priority}).`,
880	    "Tell the customer it's been created and they can follow it at /dashboard/support; the team will reply there and by email.",
881	  );
882	}
