918	    for (const i of incidents) {
919	      out.push(
920	        `  • [${i.severity}] ${i.title}${i.component ? ` (component: ${i.component})` : " (platform-wide)"} — since ${ymd(i.startedAt)}${i.body ? `\n    ${i.body.slice(0, 300)}` : ""}`,
