12	/**
13	 * Assistant orchestrator shared by POST /api/chat and /api/chat/upload.
14	 *
15	 * Owns the "should the bot speak, and how" policy so both entry points behave
16	 * identically: enablement + human-present gating, the per-conversation and
17	 * daily guardrails, the Claude answer, and the live-agent HANDOFF flow —
18	 * escalate → email an agent → open a window → if no agent joins in time, post
19	 * the "no agents available" fallback (checkEscalationTimeout, also called from
20	 * the GET poll so it fires even when the visitor sends nothing more).
21	 *
22	 * Everything here is best-effort: a throw must never break the visitor's message.
23	 */
24	
25	const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
26	const ADMIN_CHAT_URL = `${APP_URL}/admin/chat`;
27	
28	const WAIT_MSG =
29	  "Let me get a teammate for you — one moment while I see who's available. 👋";
30	const NO_AGENT_MSG =
31	  "Sorry — none of our team are free to jump in this second. I'm happy to keep helping you right here, or I can have someone personally reach out (usually within one business day). If you'd like a callback, just drop your email and a note and I'll pass it along.";
32	
33	function esc(s: string): string {
34	  return s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c] as string);
35	}
36	
37	function firstName(name: string | null): string | null {
38	  const n = (name ?? "").trim();
39	  if (!n) return null;
40	  return n.split(/\s+/)[0].slice(0, 40);
41	}
42	
43	/** Extract a hidden `[[cards: key1, key2]]` directive from a bot reply, returning
44	 *  the visible body (directive stripped) and the card keys. */
45	function parseCardDirective(reply: string): { body: string; keys: string[] } {
46	  const m = reply.match(/\[\[\s*cards?\s*:\s*([^\]]+)\]\]/i);
47	  if (!m) return { body: reply, keys: [] };
48	  const keys = m[1]
49	    .split(",")
50	    .map((s) => s.trim())
51	    .filter(Boolean);
52	  const body = reply.replace(m[0], "").replace(/\n{3,}/g, "\n\n").trim();
53	  return { body, keys };
54	}
55	
56	/** One parsed (not-yet-resolved) `[[action: type=…, id=…, label="…"]]` spec. */
57	type ActionSpec = { kind: string; id: string; label?: string };
58	
59	/** Extract every hidden `[[action: ...]]` directive from a bot reply — the
60	 *  account-action-card sibling of `[[cards: ...]]` (see lib/kb-tools.ts's
61	 *  resolveActionCard for what these become). Attribute order doesn't matter;
62	 *  unrecognized attributes are ignored. Directives are stripped from the
63	 *  visible body regardless of whether they end up resolving to a real card. */
64	function parseActionDirectives(reply: string): { body: string; specs: ActionSpec[] } {
65	  const specs: ActionSpec[] = [];
66	  const re = /\[\[\s*action\s*:\s*([^\]]+)\]\]/gi;
67	  const body = reply
68	    .replace(re, (_full, attrsRaw: string) => {
69	      const attrs: Record<string, string> = {};
70	      // key=value pairs, comma-separated; value optionally double-quoted.
71	      const attrRe = /(\w+)\s*=\s*(?:"([^"]*)"|([^,]+))/g;
72	      let am: RegExpExecArray | null;
73	      while ((am = attrRe.exec(attrsRaw)) !== null) {
74	        attrs[am[1].toLowerCase()] = (am[2] ?? am[3] ?? "").trim();
75	      }
76	      if (attrs.type && attrs.id) {
77	        specs.push({ kind: attrs.type.toLowerCase(), id: attrs.id, label: attrs.label });
78	      }
79	      return "";
80	    })
81	    .replace(/\n{3,}/g, "\n\n")
82	    .trim();
83	  return { body, specs };
84	}
85	
86	type ChatCard = (PlanCard & { type: "plan" }) | AccountActionCard;
87	
88	function toHistory(rows: { sender: string; body: string }[]): ClaudeMessage[] {
89	  return rows
90	    .filter((m) => m.body && m.body.trim())
91	    .map((m) => ({
92	      role: (m.sender === "visitor" ? "user" : "assistant") as "user" | "assistant",
93	      content: m.body,
94	    }));
95	}
