146	/**
147	 * If a conversation is waiting on a human and the window has elapsed with no
148	 * agent, post the "no agents available" fallback and clear the waiting state.
149	 * Atomic (updateMany claim) so concurrent polls can't double-post. Safe to call
150	 * on every message and every GET poll.
151	 */
152	export async function checkEscalationTimeout(conversationId: string): Promise<void> {
153	  try {
154	    const convo = await db.chatConversation.findUnique({
155	      where: { id: conversationId },
156	      select: { id: true, botEscalatedAt: true, assignedToId: true },
157	    });
158	    if (!convo?.botEscalatedAt) return;
159	
160	    // An agent joined (assigned or replied) — drop the waiting state, no fallback.
161	    const agentReplies = await db.chatMessage.count({
162	      where: { conversationId, sender: "agent" },
163	    });
164	    if (agentReplies > 0 || convo.assignedToId) {
165	      await db.chatConversation.updateMany({
166	        where: { id: conversationId, botEscalatedAt: { not: null } },
167	        data: { botEscalatedAt: null },
168	      });
169	      return;
170	    }
171	
172	    const windowSec = await getSettingInt("kb_bot_window_sec", 180);
173	    const threshold = new Date(Date.now() - windowSec * 1000);
174	    // Claim the timeout: only one caller wins, and only once the window passed.
175	    const claim = await db.chatConversation.updateMany({
176	      where: { id: conversationId, botEscalatedAt: { not: null, lte: threshold }, assignedToId: null },
177	      data: { botEscalatedAt: null },
178	    });
179	    if (claim.count !== 1) return;
180	
181	    await db.chatMessage.create({
182	      data: { conversationId, sender: "bot", body: NO_AGENT_MSG },
183	    });
184	    await mirrorChatMessageToDiscord(conversationId, NO_AGENT_MSG, "bot");
185	  } catch {
186	    /* non-essential */
187	  }
188	}
