190	/**
191	 * Evaluate the assistant for a just-received visitor message. Creates a bot
192	 * reply (or runs the handoff flow) when appropriate. `images` are the base64
193	 * blocks for an image the visitor just sent (upload path), if any.
194	 */
195	export async function runAssistant(args: {
196	  conversationId: string;
197	  visitorId: string;
198	  currentBody: string;
199	  images?: LlmImage[];
200	}): Promise<void> {
201	  try {
202	    if ((await getSetting("kb_bot_enabled", "false")) !== "true") return;
203	
204	    const convo = await db.chatConversation.findUnique({
205	      where: { id: args.conversationId },
206	      select: {
207	        id: true,
208	        visitorId: true,
209	        userId: true,
210	        name: true,
211	        email: true,
212	        assignedToId: true,
213	        botEscalatedAt: true,
214	        aiPaused: true,
215	        messages: { orderBy: { createdAt: "asc" }, select: { sender: true, body: true } },
216	      },
217	    });
218	    if (!convo) return;
219	
220	    // Staff paused the AI for this thread (admin inbox toggle) — stay silent,
221	    // exactly like the "a human already engaged" case below. The visitor's
222	    // message is already saved and flagged unreadForAgent by the caller
223	    // (POST /api/chat / the upload route), so nothing else to do here.
224	    if (convo.aiPaused) return;
225	
226	    // Never talk over a human: silent once an agent replied or was assigned.
227	    const agentReplied = convo.messages.some((m) => m.sender === "agent");
228	    if (agentReplied || convo.assignedToId) return;
229	
230	    // Already waiting on a live agent — stay quiet; just check the timeout.
231	    if (convo.botEscalatedAt) {
232	      await checkEscalationTimeout(convo.id);
233	      return;
234	    }
235	
236	    // Guardrail: per-conversation reply cap → escalate instead of looping.
237	    const botCount = convo.messages.filter((m) => m.sender === "bot").length;
238	    const maxReplies = await getSettingInt("kb_bot_max_replies", 16);
239	    if (maxReplies > 0 && botCount >= maxReplies) {
240	      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
241	      return;
242	    }
243	
244	    // Guardrail: platform-wide daily reply cap (soft cost ceiling). Over it, we
245	    // still answer — just from the token-free retrieval path (no paid call).
246	    let overDaily = false;
247	    const dailyCap = await getSettingInt("kb_bot_daily_cap", 1000);
248	    if (dailyCap > 0) {
249	      const since = new Date();
250	      since.setHours(0, 0, 0, 0);
251	      const used = await db.kbBotLog.count({
252	        where: { createdAt: { gte: since }, kind: { in: ["answer", "offer"] } },
253	      });
254	      overDaily = used >= dailyCap;
255	    }
256	
257	    const history = toHistory(convo.messages.slice(0, -1));
258	    const result = await kbAnswer(args.currentBody, {
259	      history,
260	      images: args.images,
261	      visitorName: firstName(convo.name),
262	      userId: convo.userId,
263	      noLlm: overDaily,
264	      conversationId: convo.id,
265	    });
266	
267	    // A live agent is ONLY brought in when the visitor explicitly asks for one
268	    // (humanIntent → kind "handoff"). The bot never offers or escalates on its own.
269	    if (result.kind === "handoff") {
270	      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
271	      return;
272	    }
273	
274	    if (result.reply) {
275	      // Resolve any plan cards to render with this reply: the LLM signals them
276	      // with a hidden [[cards: key1, key2]] directive; the retrieval fallback
277	      // supplies result.cardKeys. Cards are looked up from the real catalog, so
278	      // the model can only ever pick keys — prices/features are never invented.
279	      const parsedCards = parseCardDirective(result.reply);
280	      // Account-action cards are the same mechanism's sibling: [[action: ...]]
281	      // directives, resolved against THIS customer's own data (never invented —
282	      // see resolveActionCard's ownership checks). Parsed from whatever text
283	      // parseCardDirective left behind, so both directives can coexist.
284	      const parsedActions = parseActionDirectives(parsedCards.body);
285	      const keys = [...(result.cardKeys ?? []), ...parsedCards.keys];
286	      const planCards: ChatCard[] = keys.length
287	        ? getPlanCards(keys).map((c) => ({ ...c, type: "plan" as const }))
288	        : [];
289	      const actionCards = (
290	        await Promise.all(
291	          parsedActions.specs
292	            .slice(0, 3) // never render a wall of cards
293	            .map((spec) => resolveActionCard(convo.userId, spec.kind, spec.id, spec.label)),
294	        )
295	      ).filter((c): c is AccountActionCard => c !== null);
296	      const cards: ChatCard[] = [...planCards, ...actionCards];
297	      await db.chatMessage.create({
298	        data: {
299	          conversationId: convo.id,
300	          sender: "bot",
301	          body: parsedActions.body,
302	          cardsJson: cards.length ? JSON.stringify(cards) : null,
303	        },
304	      });
305	      await mirrorChatMessageToDiscord(convo.id, parsedActions.body, "bot");
306	    }
307	    // Log coverage. A HARD model failure (bad/unfunded key, API outage) is logged
308	    // as "llm_error" — distinct from an expected "degraded"/over-cap — so the
309	    // admin KB dashboard shows the bot is broken instead of it failing silently.
310	    await db.kbBotLog
311	      .create({
312	        data: {
313	          visitorId: args.visitorId,
314	          conversationId: convo.id,
315	          question: args.currentBody.slice(0, 500),
316	          kind: result.llmFailure === "error" ? "llm_error" : result.kind,
317	          matchedTitle: result.matchedTitle ?? null,
318	        },
319	      })
320	      .catch(() => {});
321	  } catch {
322	    /* assistant is non-essential — never fail the visitor's message on it */
323	  }
324	}
