function buildGameType(key: (typeof GAME_TYPE_KEYS)[number]): FreeMcGameType {
  const base = FREEMC_PRESETS[key];
  if (key === "skyblock") {
    return { ...base, extraWorldFolders: ["iridiumskyblock", "iridiumskyblock_nether", "iridiumskyblock_the_end"] };
  }
  return { ...base };
}

/** The 9 GAME TYPES. Deliberately derived from FREEMC_PRESETS rather than
 *  redeclared, so label/description/kind/type/env/setupNote/heroImage can
 *  never drift between the old and new maps — the only difference here is
